package kz.printlab.controller; import jakarta.validation.Valid; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*; import kz.printlab.dto.ProfileUpdateRequest; import kz.printlab.service.UserProfileService;
@Controller public class ProfileController {private final UserProfileService profiles; public ProfileController(UserProfileService p){profiles=p;} @GetMapping("/profile") public String profile(Model m){m.addAttribute("profileUpdateRequest",profiles.getCurrentProfile());return "profile";} @PostMapping("/profile") public String update(@Valid @ModelAttribute ProfileUpdateRequest r,BindingResult errors){if(errors.hasErrors())return "profile";profiles.updateCurrentProfile(r);return "redirect:/profile?saved";}}
